/* @lc app=leetcode id=3177 lang=kotlin */ class Solution { fun maximumLength(nums: IntArray, k: Int): Int = Array(k + 1) { HashMap<Int, Int>() }.let { maps -> IntArray(k + 1).let { maxDP -> nums.forEach { x -> (k downTo 0).forEach { j -> maxOf((maps[j][x] ?: 0) + 1, if (j > 0) maxDP[j - 1] + 1 else 1).let { v -> maps[j].put(x, v).run { maxDP[j] = maxOf(maxDP[j], v) } } } }.run { maxDP.maxOrNull() ?: 0 } } } }